#' Critical Values and p-Values for the Fourier CUSUM Test
#'
#' @description
#' Internal lookups in the three simulated tables stored in
#' \code{R/sysdata.rda} (regenerated by \code{data-raw/critical_values.R}):
#' \describe{
#'   \item{\code{fcum_plain_table}}{Xiao-Phillips CUSUM without Fourier
#'     terms, by p (T = 1000, 20,000 replications).}
#'   \item{\code{fcum_supF_table}}{sup-F pre-test for the Fourier terms, by
#'     p, kstar and grid type (T = 500, 5,000 replications).}
#'   \item{\code{fcum_cv_table}}{Fourier CUSUM at a fixed frequency, by p
#'     and k = 0.1, ..., 5 (T = 1000, 20,000 replications). Used only when
#'     \code{cv = "table"}; asymptotically valid when a break is present but
#'     conservative in finite samples because it ignores the frequency
#'     search.}
#' }
#'
#' @details
#' Version 1.0.0 of FCUSUM tabulated the 1\%, 5\% and 10\% \emph{lower}
#' quantiles of the null distribution. All tables now hold upper-tail
#' quantiles.
#'
#' @keywords internal
#' @noRd
.quant_cols <- function(tab) {
  qcols <- grep("^q", names(tab))
  list(cols = qcols, probs = as.numeric(sub("^q", "", names(tab)[qcols])))
}

.as_quantiles <- function(vals, probs) {
  names(vals) <- paste0(100 * probs, "%")
  list(quantiles = vals, probs = probs)
}

cv_plain <- function(p) {
  tab <- fcum_plain_table
  if (p > max(tab$p)) return(NULL)
  qc <- .quant_cols(tab)
  .as_quantiles(unlist(tab[tab$p == p, qc$cols]), qc$probs)
}

cv_supF <- function(p, kstar, freq) {
  tab <- fcum_supF_table
  row <- tab$p == p & tab$kstar == kstar & tab$freq == freq
  if (!any(row)) return(NULL)
  qc <- .quant_cols(tab)
  .as_quantiles(unlist(tab[row, qc$cols]), qc$probs)
}

cv_fixed <- function(p, k) {
  tab <- fcum_cv_table
  if (p > max(tab$p) || k < min(tab$k) || k > max(tab$k)) return(NULL)
  sub <- tab[tab$p == p, , drop = FALSE]
  qc <- .quant_cols(sub)
  vals <- vapply(qc$cols, function(j) stats::approx(sub$k, sub[[j]], xout = k)$y,
                 numeric(1))
  .as_quantiles(vals, qc$probs)
}

#' Critical values (10%, 5%, 1%) and p-value from null quantiles or draws
#' @keywords internal
#' @noRd
cv_summary <- function(stat, quantiles = NULL, probs = NULL, draws = NULL) {
  if (!is.null(draws)) {
    cv <- stats::quantile(draws, c(0.90, 0.95, 0.99), names = FALSE)
    names(cv) <- c("10%", "5%", "1%")
    pval <- (1 + sum(draws >= stat)) / (length(draws) + 1)
    return(list(critical_values = cv, p.value = pval,
                p.label = format.pval(pval, digits = 3)))
  }
  pick <- function(pr) unname(quantiles[which.min(abs(probs - pr))])
  cv <- c("10%" = pick(0.90), "5%" = pick(0.95), "1%" = pick(0.99))
  if (stat >= max(quantiles)) {
    pval <- 1 - max(probs); plabel <- paste0("< ", format(pval))
  } else if (stat <= min(quantiles)) {
    pval <- 1 - min(probs); plabel <- paste0("> ", format(pval))
  } else {
    pval <- 1 - stats::approx(quantiles, probs, xout = stat, ties = "ordered")$y
    plabel <- format(round(pval, 3), nsmall = 3)
  }
  list(critical_values = cv, p.value = pval, p.label = plabel)
}

# Decision text and stars -------------------------------------------------------
.decide <- function(stat, cv) {
  if (stat > cv["1%"]) {
    list(decision = "Reject H0 (cointegration) at the 1% level", significance = "***")
  } else if (stat > cv["5%"]) {
    list(decision = "Reject H0 (cointegration) at the 5% level", significance = "**")
  } else if (stat > cv["10%"]) {
    list(decision = "Reject H0 (cointegration) at the 10% level", significance = "*")
  } else {
    list(decision = "Fail to reject H0: evidence of cointegration", significance = "")
  }
}
